        self._customers: dict[str, bool] = {}
        self._tickets: dict[int, dict] = {}
        self._queue: list[tuple] = []
        self._ids = count(1)
        self._seq = count(0)

    def add_customer(self, name: str, vip: bool = False) -> None:
        self._customers[name] = vip

    def open_ticket(
        self,
        customer: str,
        title: str,
        priority: str = "normal",
        description: str = "",
    ) -> int:
        if not title:
            raise ValueError("Title cannot be empty")
        if customer not in self._customers:
            raise ValueError(f"Unknown customer: {customer}")
        if priority not in self.PRIORITIES:
            raise ValueError(f"Invalid priority: {priority}")

        ticket_id = next(self._ids)
        vip = self._customers[customer]
        prio_rank = self.PRIORITIES.index(priority)

        self._tickets[ticket_id] = {
            "customer": customer,
            "title": title,
            "priority": priority,
            "status": "open",
            "description": description,
        }
        # VIP tickets sort first, then by priority rank descending (critical > high > normal),
        # then by opening order (FIFO).
        heap_key = (0 if vip else 1, -prio_rank, next(self._seq), ticket_id)
        heapq.heappush(self._queue, heap_key)
        return ticket_id

    def next_ticket(self) -> int | None:
        while self._queue:
            _, _, _, ticket_id = heapq.heappop(self._queue)
            ticket = self._tickets.get(ticket_id)
            if ticket is None or ticket["status"] != "open":
                continue
            ticket["status"] = "in_progress"
            return ticket_id
        return None

    def close(self, ticket_id: int) -> None:
        if ticket_id not in self._tickets:
            raise ValueError(f"Unknown ticket: {ticket_id}")
        self._tickets[ticket_id]["status"] = "closed"

    def reopen(self, ticket_id: int) -> None:
        if ticket_id not in self._tickets:
            raise ValueError(f"Unknown ticket: {ticket_id}")
        ticket = self._tickets[ticket_id]
        if ticket["status"] == "closed":
            raise ValueError(f"Cannot reopen closed ticket: {ticket_id}")
        if ticket["status"] == "open":
            return
        # Was in_progress -> put back into queue.
        vip = self._customers[ticket["customer"]]
        prio_rank = self.PRIORITIES.index(ticket["priority"])
        ticket["status"] = "open"
        heap_key = (0 if vip else 1, -prio_rank, next(self._seq), ticket_id)
        heapq.heappush(self._queue, heap_key)

    def ticket(self, ticket_id: int) -> dict:
        if ticket_id not in self._tickets:
            raise ValueError(f"Unknown ticket: {ticket_id}")
        return dict(self._tickets[ticket_id])

    def queue_length(self) -> int:
        """Return the number of tickets currently waiting in the queue."""
        return sum(
            1
            for _, _, _, ticket_id in self._queue
            if ticket_id in self._tickets
            and self._tickets[ticket_id]["status"] == "open"
        )
